WITH matched_keys AS (SELECT method, status FROM payments EXCEPT ALL SELECT method, status FROM payments WHERE HOUR(paid_at) BETWEEN 8 AND 14), kept_rows AS (SELECT s.* FROM payments s INNER JOIN matched_keys k ON s.method = k.method AND s.status = k.status) SELECT s.id, s.order_id, s.method, s.paid_at, s.status, CASE WHEN method RLIKE '^(card|bank_transfer)$' THEN 'OTHER_ZONE' WHEN method RLIKE '^(paypal|cash)$' THEN 'GROUP_B' ELSE 'GROUP_A' END AS method_zone, (SELECT SUM(x.amount) FROM payments x WHERE x.order_id = s.order_id) AS sum_payment_amount FROM kept_rows s;
